styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  column-gap: var(--g-gap);
  position: relative;

  padding-bottom: calc(var(--vh, 1vh) * 80);
}
@media (min-width: 1024px) {
}
section[data-skill-hub] .-w .note {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;
  justify-self: center;
  align-self: start;
  text-align: center;
  z-index: 40;
  margin-top: var(--h0);
  background-color: var(--c-black);
}
section[data-skill-hub] .-w p {
  grid-column-start: 3;
  grid-column-end: 13;
  grid-row-start: 1;
  justify-self: center;
  align-self: start;
  text-align: center;
  z-index: 40;
  margin-top: calc(var(--h1) * 2);
  padding-left: 10%;
  padding-right: 10%;

  @media (min-width: 1024px) {
    grid-column-start: 6;
    grid-column-end: 10;
  }
}

section[data-skill-hub] .-w figure {
  grid-row-start: 2;
  margin-top: calc(var(--vh, 1vh) * 10);
  transform: translateZ(0);
  clip-path: inset(0% 0% 0% 0%);
}
section[data-skill-hub] .-w .image-1 {
  grid-column-start: 1;
  grid-column-end: 3;

  @media (min-width: 1024px) {
    grid-column-start: 3;
    grid-column-end: 5;
  }
}
section[data-skill-hub] .-w .image-2 {
  grid-column-start: 3;
  grid-column-end: 6;

  @media (min-width: 1024px) {
    grid-column-start: 5;
    grid-column-end: 7;
  }
}
section[data-skill-hub] .-w .image-3 {
  grid-column-start: 6;
  grid-column-end: 10;

  @media (min-width: 1024px) {
    grid-column-start: 7;
    grid-column-end: 9;
  }
}
section[data-skill-hub] .-w .image-4 {
  grid-column-start: 10;
  grid-column-end: 13;

  @media (min-width: 1024px) {
    grid-column-start: 9;
    grid-column-end: 11;
  }
}
section[data-skill-hub] .-w .image-5 {
  grid-column-start: 13;
  grid-column-end: 15;

  @media (min-width: 1024px) {
    grid-column-start: 11;
    grid-column-end: 13;
  }
}
